(function(){"use strict";function f(c,a){const s=[],t=c.split(/\r?\n/);if(t.length<2)return s;const i=t[0].split("|").map(n=>n.trim().toLowerCase()),l=i.findIndex(n=>n==="symbol"||n==="nasdaq symbol"),u=i.findIndex(n=>n.includes("security name")||n==="name"||n==="description"),r=i.findIndex(n=>n==="exchange"||n==="listing exchange"),m=i.findIndex(n=>n==="test issue");for(const n of t.slice(1)){const d=n.trim();if(!d||d.startsWith("File Creation Time"))continue;const e=d.split("|");if(m>=0&&(e[m]??"").trim().toUpperCase()==="Y")continue;const o=(e[l]??"").trim();!o||o.includes(" ")||l<0||s.push({symbol:o,name:(e[u]??o).trim(),exchange:r>=0&&e[r]?e[r].trim():a})}return s}self.onmessage=c=>{const{text:a,fallbackExchange:s}=c.data,t=f(a,s);self.postMessage(t)}})();
